/* The four scans make-cd-image.html draws with, inlined as data URIs.
   They are here rather than loaded as .png files because a page opened
   straight off the filesystem treats a sibling file:// image as
   cross-origin: it draws fine and then taints the canvas, so toBlob
   throws and nothing can be saved. A classic script has no such rule,
   and a data: URI taints nothing, so the page works the same opened
   locally as it does served.

   Generated from the full-size PNGs beside this file, resized to the
   1000x1000 the canvas draws them at:

     for f in cd case plastic tape; do
       convert "$f.png" -resize 1000x1000 -strip \
         -define png:compression-level=9 "scaled/$f.png"
     done
*/
window.CD_SCANS = {
  disc: "data:image/png;base64,",
  gloss: "data:image/png;base64,",
  plastic: "data:image/png;base64,",
  tape: "data:image/png;base64,",
};
